// spec: .qa/e2e/specs/post-create.md · seed: tests/seed.free.spec.ts · кейс .qa/tests/post-create/PC-01.md
import { test, expect } from '@playwright/test';
import { saveSession } from '../_shared/session';
import { IPHONE, authFile, form, openComposer } from './post-helpers';

test.use({ ...IPHONE, storageState: authFile('free') });

test.describe('מסך יצירת פוסט', () => {
  test('Открытие формы из ленты: заголовок, поле, «הוספת תמונה», «לפרסם» неактивна @iphone @prod-safe (#1ff0f4)', async ({ page }) => {
    try {
      // 1–2. /social → FAB «פוסט חדש» (тап после ухода сплэша)
      await openComposer(page);
      const f = form(page);
      // Ожидаемо: шапка «פוסט חדש» + ✕, поле с placeholder, ячейка фото, «לפרסם» disabled (AC1–2, Figma 09.19)
      await expect(page).toHaveURL(/\/post\/new$/);
      await expect(f.close).toBeVisible();
      await expect(f.text).toBeVisible();
      await expect(f.text).toHaveAttribute('placeholder', 'מה בא לך לשתף?');
      await expect(f.text).toBeEditable();
      await expect(f.addPhoto).toBeVisible();
      await expect(f.publish).toBeDisabled();
      // AC2: в поле можно ввести текст
      await f.text.fill('בדיקה');
      await expect(f.text).toHaveValue('בדיקה');
    } finally {
      await saveSession(page, 'free');
    }
  });
});
